{
    if (!ucishangul(code))
      return 0;

    code -= 0xac00;
    decomp[0] = 0x1100 + (krb5_ui_4) (code / 588);
    decomp[1] = 0x1161 + (krb5_ui_4) ((code % 588) / 28);
    decomp[2] = 0x11a7 + (krb5_ui_4) (code % 28);
    *num = (decomp[2] != 0x11a7) ? 3 : 2;

    return 1;
}

